        code: "# platform/metrics.yaml — what the platform team reviews weekly, and where it comes from.\nmetrics:\n  - id: time_to_first_deploy\n    question: \"How long from scaffolding a service to its first production deploy?\"\n    source: catalog + deployment events\n    target: \"< 1 day (p75)\"\n\n  - id: dora_on_vs_off_path\n    question: \"Do teams on the paved road deliver better than teams off it?\"\n    source: deployment events grouped by template-version annotation\n    target: \"lead time and change fail rate better on path\"\n\n  - id: fulfilment_latency\n    question: \"How long from requesting a capability to using it?\"\n    source: platform API resource created -> Ready condition\n    target: \"p95 < 15 min for GA capabilities\"\n\n  - id: voluntary_adoption\n    question: \"What share of new services chose the paved road with no mandate?\"\n    source: catalog entities created in the last 90 days\n    target: \"> 80%\"\n\n  - id: support_load\n    question: \"Which capability generates the most questions?\"\n    source: support channel threads tagged by capability\n    target: \"no capability above 20% of total\"\n\n# Deprecation is a product process, not a deletion.\ndeprecations:\n  - capability: pipeline-template-v3\n    announced: 2026-07-01\n    removal: 2026-10-01                # 90 days, published up front\n    migration: \"automated pull request to v4; platform team pairs with any team that asks\"\n    remaining_consumers: 6             # tracked in the portal until zero",
